class Solution {
public:
    int getMaximumGenerated(int n) {
        if (n == 0) return 0;
        vector<int> nums(n + 1, 0);
        nums[1] = 1;
        for (int i = 2; i <= n; ++i) {
            int half = i / 2;
            nums[i] = (i % 2 == 0) ? nums[half] : nums[half] + nums[half + 1];
        }
        return *max_element(nums.begin(), nums.end());
    }
};

