class Solution {
    public int getMaximumGenerated(int n) {
        if (n == 0) return 0;
        int[] nums = new int[n + 1];
        nums[1] = 1;
        for (int i = 2; i <= n; i++) {
            int half = i / 2;
            nums[i] = (i % 2 == 0) ? nums[half] : nums[half] + nums[half + 1];
        }
        int best = 0;
        for (int x : nums) best = Math.max(best, x);
        return best;
    }
}

