from functools import lru_cache


class Solution:
    def getMaximumGenerated(self, n: int) -> int:
        @lru_cache(maxsize=None)
        def gen(i: int) -> int:
            if i <= 1:
                return i
            if i % 2 == 0:
                return gen(i // 2)
            return gen(i // 2) + gen(i // 2 + 1)

        return max(gen(i) for i in range(n + 1))

