class Solution {
    vector<int> memo;

    int gen(int i) {
        int& res = memo[i];
        if (res >= 0) return res;
        if (i <= 1) return res = i;
        if (i % 2 == 0) return res = gen(i / 2);
        return res = gen(i / 2) + gen(i / 2 + 1);
    }

public:
    int getMaximumGenerated(int n) {
        memo.assign(n + 1, -1);
        int best = 0;
        for (int i = 0; i <= n; ++i) best = max(best, gen(i));
        return best;
    }
};

