class Solution {
    private Integer[] memo;

    private int gen(int i) {
        if (i <= 1) return i;
        if (memo[i] != null) return memo[i];
        int res = (i % 2 == 0) ? gen(i / 2) : gen(i / 2) + gen(i / 2 + 1);
        return memo[i] = res;
    }

    public int getMaximumGenerated(int n) {
        memo = new Integer[n + 1];
        int best = 0;
        for (int i = 0; i <= n; i++) best = Math.max(best, gen(i));
        return best;
    }
}

