var getMaximumGenerated = function(n) {
    const memo = new Array(n + 1).fill(undefined);
    const gen = (i) => {
        if (i <= 1) return i;
        if (memo[i] !== undefined) return memo[i];
        memo[i] = (i % 2 === 0) ? gen(i >> 1) : gen(i >> 1) + gen((i >> 1) + 1);
        return memo[i];
    };
    let best = 0;
    for (let i = 0; i <= n; i++) best = Math.max(best, gen(i));
    return best;
};
